local function viewport()
    local current = workspace.CurrentCamera or camera
    return current and current.ViewportSize or vector2(1920, 1080)
end
local function finite(value)
    return type(value) == "number" and value == value and math_abs(value) < math.huge
end
local decodedImages = {}
local function fetchImage(name)
    if decodedImages[name] then
        return decodedImages[name]
    end
    local data = ASSET_IMAGES[name .. ".png"]
    if not data then
        return
    end
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local output, accumulator, bits = {}, 0, 0
    for i = 1, #data do
        local char = data:sub(i, i)
        if char == "=" then
            break
        end
        local index = alphabet:find(char, 1, true)
        if index then
            accumulator = accumulator * 64 + index - 1
            bits += 6
            if bits >= 8 then
                bits -= 8
                output[#output + 1] = string.char(math.floor(accumulator / 2 ^ bits))
                accumulator %= 2 ^ bits
            end
        end
    end
    decodedImages[name] = table.concat(output)
    return decodedImages[name]
end

local createDrawing = function(_type, properties, ...)
    local drawing = drawing_new(_type == "RoundedSquare" and "Square" or _type)
    if _type == "RoundedSquare" then
        drawing.Filled = true
        drawing.Transparency = 1
    end
    for index, value in properties do
        if index ~= "Rounding" then
            drawing[index] = value
        end
    end
    for _, _table in { ... } do
        table_insert(_table, drawing)
    end
    return drawing
end
