local function square(owner, list, position, size, colour, z, filled)
    return createDrawing("Square", {
        Visible = true,
        Filled = filled ~= false,
        Transparency = 1,
        Thickness = 1,
        Position = position,
        Size = size,
        Color = colour,
        ZIndex = z,
    }, owner.allDrawings, list)
end
local function label(owner, list, position, text, colour, z, center)
    return createDrawing("Text", {
        Visible = true,
        Outline = true,
        OutlineColor = palette.border,
        Transparency = 1,
        Font = GLOBAL_FONT,
        Size = GLOBAL_SIZE,
        Text = text,
        Color = colour,
        Position = position,
        ZIndex = z,
        Center = center or false,
    }, owner.allDrawings, list)
end
local function connect(owner, signal, callback)
    owner.connections = owner.connections or {}
    for i = #owner.connections, 1, -1 do
        if not owner.connections[i].Connected then
            table_remove(owner.connections, i)
        end
    end
    local connection = signal:Connect(callback)
    table_insert(owner.connections, connection)
    return connection
end
local windows = {}
local function receivesMouse(owner, point)
    for _, window in windows do
        if
            window ~= owner
            and window.active
            and not window.destroyed
            and window.baseZindex > (owner.baseZindex or 0)
        then
            local base = window.drawings.base
            local delta = point - base.Position
            if delta.X >= 0 and delta.Y >= 0 and delta.X < base.Size.X and delta.Y < base.Size.Y then
                return false
            end
        end
    end
    return true
end
local function stopDrag(owner)
    owner.mouseHeld = false
    if owner.dragConnection then
        owner.dragConnection:Disconnect()
        owner.dragConnection = nil
    end
end
local function startDrag(owner, callback)
    stopDrag(owner)
    if owner.destroyed or owner.active == false then
        return
    end
    owner.mouseHeld = true
    owner.dragConnection = connect(owner, runService.RenderStepped, function()
        if owner.destroyed or not owner.mouseHeld then
            stopDrag(owner)
            return
        end
        callback()
    end)
    callback()
end
local function moveFromMouse(owner, mousePosition)
    local previous = mousePosition
    startDrag(owner, function()
        local mouse = userInputService:GetMouseLocation()
        local base, view = owner.drawings.base, viewport()
        local nextPosition = base.Position + mouse - previous
        local minX, maxX = math.min(0, 32 - base.Size.X), math.max(0, view.X - 32)
        nextPosition = vector2(
            math_round(math_clamp(nextPosition.X, minX, maxX)),
            math_round(math_clamp(nextPosition.Y, 0, math.max(0, view.Y - 24)))
        )
        local delta = nextPosition - base.Position
        for _, drawing in owner.allDrawings do
            drawing.Position += delta
        end
        owner.position = owner.tabSettings and nextPosition + owner.size / 2 or nextPosition
        previous = mouse
    end)
end
local function cancelCapture(window)
    local picker = window.capture
    window.capture = nil
    if picker and not window.destroyed then
        picker.active = false
        picker:update()
    end
end
local function closePopup(window)
    local picker = window.popup
    window.popup = nil
    if not picker or window.destroyed then
        return
    end
    stopDrag(window)
    for _, drawing in picker.onToggle do
        drawing.Visible = false
    end
    for _, entry in window.cachedImages do
        if entry.toggle then
            entry.drawing.Visible = false
        end
    end
end
local function fitText(drawing, value, width)
    local text = tostring(value or "")
    width = math.max(width, 0)
    drawing.Text = text
    if drawing.TextBounds.X <= width then
        return
    end
    drawing.Text = "..."
    if drawing.TextBounds.X > width then
        drawing.Text = ""
        return
    end
    local unicodeLength = utf8.len(text)
    local low, high, best = 0, unicodeLength or #text, ""
    while low <= high do
        local middle = math.floor((low + high) / 2)
        local last = unicodeLength and ((utf8.offset(text, middle + 1) or (#text + 1)) - 1) or middle
        local candidate = text:sub(1, last) .. "..."
        drawing.Text = candidate
        if drawing.TextBounds.X <= width then
            best = candidate
            low = middle + 1
        else
            high = middle - 1
        end
    end
    drawing.Text = best
end
local function layoutToggle(toggle)
    if toggle.window.destroyed then
        return
    end
    local d = toggle.drawings
    local right = d.outline.Position.X + toggle.window.drawings.sectionOutline1.Size.X - 26
    if toggle.hasColourpicker then
        right -= 30
    end
    if toggle.keypicker then
        right = math.min(right, toggle.keypicker.drawings.text.Position.X - 8)
    end
    fitText(d.text, toggle.text, right - d.text.Position.X)
    d.clickDetector.Size = vector2(math.max(11, math.min(right - d.outline.Position.X, 20 + d.text.TextBounds.X)), 16)
end
local function formatValue(value, increment)
    local precision = math_clamp(math.ceil(-math.log10(increment)) + 2, 0, 10)
    local text = string.format("%." .. precision .. "f", value)
    if string_find(text, ".", 1, true) then
        text = text:gsub("0+$", ""):gsub("%.$", "")
    end
    return text == "-0" and "0" or text
end
local function updateSlider(slider)
    local d = slider.drawings
    d.accent.Size = vector2((d.outline.Size.X - 2) * (slider.value - slider.min) / slider.range, d.accent.Size.Y)
    fitText(d.value, formatValue(slider.value, slider.increment) .. slider.suffix, d.outline.Size.X)
    d.value.Position = d.text.Position + vector2(d.outline.Size.X - d.value.TextBounds.X, 0)
    fitText(d.text, slider.text, d.outline.Size.X - d.value.TextBounds.X - 10)
end
local function destroy(owner)
    if owner.destroyed then
        return
    end
    owner.destroyed = true
    owner.cleanupErrors = {}
    local function cleanup(callback)
        local ok, problem = pcall(callback)
        if not ok then owner.cleanupErrors[#owner.cleanupErrors + 1] = tostring(problem) end
    end
    cleanup(function() stopDrag(owner) end)
    for _, instance in ipairs(owner.instances or {}) do cleanup(function() instance:Destroy() end) end
    for _, flag in ipairs(owner.flagObjects or {}) do
        table.clear(flag.listeners); table.clear(flag.keyListeners)
    end
    table.clear(owner.instances or {})
    local windowIndex = table_find(windows, owner)
    if windowIndex then
        table_remove(windows, windowIndex)
    end
    for _, connection in owner.connections or {} do
        cleanup(function() connection:Disconnect() end)
    end
    for _, notification in table.clone(owner.ownedNotifications or owner.notifications or {}) do
        cleanup(function() notification:destroy() end)
    end
    for _, drawing in owner.allDrawings or owner.drawings do
        cleanup(function() drawing:Remove() end)
    end
    table.clear(owner.connections or {})
    table.clear(owner.allDrawings or owner.drawings)
end

local function newFlag(control, kind, value, options)
    local window = control.window
    local flag = {type=kind, value=value, self=control, ignoreConfig=options.ignoreConfig == true,
        available=true, listeners={}, keyListeners={}}
    local function subscribe(list, callback, current)
        assert(type(callback) == "function", "A setting listener must be a function.")
        local entry = {callback=callback, connected=true}
        list[#list+1] = entry
        local ok, problem = pcall(callback, current)
        if not ok then
            entry.connected = false
            local index = table.find(list, entry)
            if index then table.remove(list, index) end
            error(problem, 0)
        end
        return function()
            entry.connected=false
            local index=table.find(list,entry)
            if index then table.remove(list,index) end
        end
    end
    local function dispatch(list, current)
        if not flag.available then
            flag.value, control.enabled = false, false
            if control.drawings and control.drawings.accent then control.drawings.accent.Transparency=0 end
            if current then window:notify(flag.unavailableReason or "This feature is unavailable.",4) end
            return
        end
        local failed, firstError = false, nil
        for _, entry in ipairs(table.clone(list)) do
            if window.destroyed then break end
            if entry.connected then
                local ok, problem = pcall(entry.callback, current)
                if not ok and not failed then failed, firstError = true, problem end
            end
        end
        if failed then error(firstError, 0) end
    end
    function flag:OnChanged(callback)
        if not self.available then return function() end end
        return subscribe(self.listeners,callback,self.value)
    end
    function flag:OnKeyChanged(callback) return subscribe(self.keyListeners,callback,self.key) end
    function flag:SetAvailable(available, reason)
        local ok, problem = true, nil
        if not available and self.available and (self.type == "toggle" or self.type == "keypicker") then
            ok, problem = pcall(control.setValue, false, self.key)
        end
        self.available, self.unavailableReason=available,reason
        if not available then
            table.clear(self.listeners); table.clear(self.keyListeners)
        end
        if not ok then error(problem, 0) end
    end
    flag.Changed=function(current) dispatch(flag.listeners,current) end
    flag.KeyChanged=function(current) dispatch(flag.keyListeners,current) end
    if kind=="keypicker" then flag.key=control.value end
    if options.flag then window.flags[options.flag]=flag end
    window.flagObjects=window.flagObjects or {};window.flagObjects[#window.flagObjects+1]=flag
    return flag
end

local createClass = function(_table: table?): table
    local class = _table or {}
    class.__index = class
    return class
end

