notifyClass.new = function(window, text, time)
    local notification = setmetatable({
        window = window,
        text = text,
        time = finite(time) and math.max(0.05, time) or 3,

        active = true,
        drawings = {},
    }, notifyClass)

    local notificationOffset = 65

    local notifications = window.notifications
    for i = 1, #notifications do
        notificationOffset += notifications[i].offset + 10
    end

    do
        local drawings = notification.drawings

        drawings.text = createDrawing("Text", {
            Visible = true,
            Center = false,
            Outline = true,
            Transparency = 1,
            Size = GLOBAL_SIZE,
            Font = GLOBAL_FONT,
            Text = text,
            Color = palette.text,
            OutlineColor = color_rgb(0, 0, 0),
            ZIndex = 9,
        })
        fitText(drawings.text, text, viewport().X - 30)
        drawings.text.Position = vector2(-drawings.text.TextBounds.X - 5, notificationOffset + 5)

        drawings.background = createDrawing("Square", {
            Visible = true,
            Filled = true,
            Transparency = 1,
            Thickness = 1,
            Color = palette.base,
            Position = drawings.text.Position - vector2(5, 5),
            Size = drawings.text.TextBounds + vector2(10, 10),
            ZIndex = 8,
        })

        drawings.background_outline = createDrawing("Square", {
            Visible = true,
            Filled = false,
            Transparency = 1,
            Thickness = 1,
            Color = color_rgb(0, 0, 0),
            Position = drawings.background.Position,
            Size = drawings.background.Size,
            ZIndex = 9,
        })

        drawings.accent = createDrawing("Square", {
            Visible = true,
            Filled = true,
            Transparency = 1,
            Thickness = 1,
            Color = window.accent or palette.accent,
            Position = drawings.background.Position - vector2(2, 0),
            Size = drawings.background.Size + vector2(2, 2),
            ZIndex = 7,
        })
    end

    notification.offset = notification.drawings.accent.Size.Y
    notification.goalPos = vector2(10, notificationOffset)
    notification:moveTo(notification.goalPos, 0.2)
    table_insert(notifications, notification)
    window.ownedNotifications = window.ownedNotifications or {}
    table_insert(window.ownedNotifications, notification)

    local totalTime = 0
    notification.connection = connect(notification, runService.RenderStepped, function(deltaTime)
        totalTime += deltaTime

        if totalTime >= notification.time - 0.05 then
            notification.connection:Disconnect()
            notification:remove()
            return
        end
    end)

    return notification
end
boardClass.new = function(options: table)
    options = options or {}
    local size = options.size or vector2(180, 80)
    size = vector2(math.max(40, math_round(size.X)), math.max(27, math_round(size.Y)))

    local board = setmetatable({
        active = options.active == true,
        title = options.title or "",
        size = size,
        position = options.position or vector2(viewport().X - size.X - 10, viewport().Y / 2 - size.Y / 2),
        mouseHeld = false,

        storage = {},
        storedText = {},
        clickDetectors = {},

        drawings = {},
        cachedDrawings = {},
        allDrawings = {},
    }, boardClass)

    do
        local drawings = board.drawings

        drawings.base = createDrawing("Square", {
            Visible = board.active,
            Filled = true,
            Transparency = 1,
            Thickness = 1,
            Color = palette.base,
            Position = board.position,
            Size = board.size,
            ZIndex = 8,
        }, board.allDrawings)

        drawings.onDrag = createDrawing("Square", {
            Visible = board.active,
            Filled = false,
            Transparency = 0,
            Thickness = 1,
            Color = palette.base,
            Position = drawings.base.Position,
            Size = vector2(board.size.X, 22),
            ZIndex = 0,
        }, board.allDrawings)

        drawings.baseOutline = createDrawing("Square", {
            Visible = board.active,
            Filled = false,
            Transparency = 1,
            Thickness = 1,
            Color = palette.border,
            Position = drawings.base.Position - vector2(1, 1),
            Size = drawings.base.Size + vector2(2, 2),
            ZIndex = 9,
        }, board.allDrawings)

        drawings.title = createDrawing("Text", {
            Visible = board.active,
            Center = false,
            Outline = true,
            Transparency = 1,
            Size = GLOBAL_SIZE,
            Font = GLOBAL_FONT,
            Text = board.title,
            Color = color_rgb(255, 255, 255),
            OutlineColor = color_rgb(0, 0, 0),
            Position = drawings.base.Position + vector2(8, 7),
            ZIndex = 9,
        }, board.allDrawings)
    end

    do
        local d = board.drawings
        d.accent = square(
            board,
            nil,
            d.base.Position + vector2(1, 1),
            vector2(board.size.X - 2, 2),
            options.accent or palette.accent,
            10
        )
        d.separator =
            square(board, nil, d.base.Position + vector2(1, 24), vector2(board.size.X - 2, 1), palette.edge, 10)
        d.accent.Visible = board.active
        d.separator.Visible = board.active
        fitText(d.title, board.title, board.size.X - 16)
        local clickDetectors = board.clickDetectors

        connect(board, userInputService.InputBegan, function(input, gameProcessed)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                return
            end
            if not board.active or not receivesMouse(board, userInputService:GetMouseLocation()) then
                return
            end
            board.mouseHeld = true

            local mousePosition = userInputService:GetMouseLocation()
            for i = 1, #clickDetectors do
                if board.destroyed or not board.active then
                    break
                end
                clickDetectors[i](mousePosition)
            end
        end)

        connect(board, userInputService.InputEnded, function(input, gameProcessed)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                return
            end
            stopDrag(board)
        end)

        local onDrag = function(mousePosition)
            moveFromMouse(board, mousePosition)
        end
        board:onClick(board.drawings.onDrag, onDrag)
    end

    if userInputService.WindowFocusReleased then
        connect(board, userInputService.WindowFocusReleased, function()
            stopDrag(board)
        end)
    end
    return board
end
