        d.accent.Visible = targetHUD.active
        local clickDetectors = targetHUD.clickDetectors

        connect(targetHUD, userInputService.InputBegan, function(input, gameProcessed)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                return
