            stopDrag(targetHUD)
        end)

        local onDrag = function(mousePosition)
            moveFromMouse(targetHUD, mousePosition)
        end
        targetHUD:onClick(targetHUD.drawings.base, onDrag)
    end

    if userInputService.WindowFocusReleased then
        connect(targetHUD, userInputService.WindowFocusReleased, function()
            stopDrag(targetHUD)
        end)
    end
    return targetHUD
end

windowClass.new = function(options: table)
    assert(type(options) == "table", `invalid argument #1 to 'windowClass.new' (table expected, got {type(options)})`)
    windowClass.index += 1

    local window = setmetatable({
        baseZindex = 100 + windowClass.index * 32,

        id = windowClass.index,
        active = true,
        title = options.title or "Window",
        size = options.size or vector2(600, 500),
        position = options.position or viewport() // 2,
        accent = options.accent or palette.accent,
        notifications = {},

        tabSettings = {
            index = 0,
            tabs = {},
        },

        cachedImages = {},
        clickDetectors = {},
        keyDetectors = {},
        keyEnd = {},
        flags = {},
        connectedToggles = {},

        drawings = {},
        allDrawings = {},
        overlapDrawings = {},
    }, windowClass)

    do
        local d, z = window.drawings, window.baseZindex
        window.size = vector2(math.max(320, math_round(window.size.X)), math.max(180, math_round(window.size.Y)))
        local pos, size = window.position - window.size / 2, window.size
        d.base = square(window, nil, pos, size, palette.base, z + 1)
        d.baseOutline = square(window, nil, pos - vector2(1, 1), size + vector2(2, 2), palette.border, z + 2, false)
        d.bevel = square(window, nil, pos + vector2(1, 1), size - vector2(2, 2), palette.edge, z + 2, false)
        d.titlebar = square(window, nil, pos + vector2(2, 2), vector2(size.X - 4, 25), palette.raised, z + 2)
        d.accent = square(window, nil, pos + vector2(2, 2), vector2(size.X - 4, 2), window.accent, z + 3)
        d.title = label(window, nil, pos + vector2(10, 8), window.title, palette.text, z + 3)
        fitText(d.title, window.title, size.X - 20)
        d.onDrag = square(window, nil, pos, vector2(size.X, 27), palette.base, 0)
        d.onDrag.Transparency = 0
        d.innerOutline =
            square(window, nil, pos + vector2(8, 33), vector2(size.X - 16, 27), palette.border, z + 2, false)
        d.innerOutline2 =
            square(window, nil, pos + vector2(8, 68), size - vector2(16, 76), palette.border, z + 2, false)
        local panelSize = vector2(math.floor((size.X - 25) / 2), size.Y - 76)
        d.sectionFill1 = square(window, nil, pos + vector2(8, 68), panelSize, palette.panel, z + 2)
        d.sectionOutline1 = square(window, nil, d.sectionFill1.Position, panelSize, palette.border, z + 3, false)
        d.sectionFill2 = square(window, nil, pos + vector2(17 + panelSize.X, 68), panelSize, palette.panel, z + 2)
        d.sectionOutline2 = square(window, nil, d.sectionFill2.Position, panelSize, palette.border, z + 3, false)
        d.sectionBevel1 = square(
            window,
            nil,
            d.sectionFill1.Position + vector2(1, 1),
            panelSize - vector2(2, 2),
            palette.edge,
            z + 3,
            false
        )
        d.sectionBevel2 = square(
            window,
            nil,
            d.sectionFill2.Position + vector2(1, 1),
            panelSize - vector2(2, 2),
            palette.edge,
            z + 3,
            false
        )
    end

    do
        local clickDetectors = window.clickDetectors
        local keyDetectors = window.keyDetectors
        local keyEnd = window.keyEnd

        connect(window, userInputService.InputBegan, function(input, gameProcessed)
            local capturing = window.capture
            if capturing and input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                capturing.onKeyPress(input)
                return
            end
            if input.KeyCode == Enum.KeyCode.Escape and window.popup then
                closePopup(window)
                return
            end
            for i = 1, #keyDetectors do
                if window.destroyed then
                    return
                end
                keyDetectors[i](input, gameProcessed)
            end
            if window.destroyed then
                return
            end

            if input.KeyCode == Enum.KeyCode.RightShift and not userInputService:GetFocusedTextBox() then
                return window:toggle()
            elseif input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                return
            end

            if not window.active or not receivesMouse(window, userInputService:GetMouseLocation()) then
                return
            end
            window.mouseHeld = true

            local mousePosition = userInputService:GetMouseLocation()
            local popup = window.popup
            if
                popup
                and not window:isWithin(popup.drawings.background_outline, mousePosition)
                and not window:isWithin(popup.drawings.colour_outline, mousePosition)
            then
                closePopup(window)
                return
            end
            if window.capture and not window:isWithin(window.capture.drawings.clickDetector, mousePosition) then
                cancelCapture(window)
            end
            for i = 1, #clickDetectors do
                if window.destroyed or not window.active then
                    break
                end
                clickDetectors[i](mousePosition)
                if window.popup ~= popup then
                    break
                end
            end
        end)

        connect(window, userInputService.InputEnded, function(input, gameProcessed)
            for i = 1, #keyEnd do
                if window.destroyed then
                    return
                end
                keyEnd[i](input, gameProcessed)
            end

            if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                return
            end
            stopDrag(window)
        end)

        local onDrag = function(mousePosition)
            moveFromMouse(window, mousePosition)
        end
        window:onClick(window.drawings.onDrag, onDrag)
    end

    table_insert(windows, window)
    if userInputService.WindowFocusReleased then
        connect(window, userInputService.WindowFocusReleased, function()
            stopDrag(window)
            cancelCapture(window)
            closePopup(window)
            for _, picker in window.keypickers or {} do
                if window.destroyed then
                    break
                end
                if picker.mode ~= "toggle" and picker.flag.value then
                    picker.flag.value = false
                    picker.flag.Changed(false)
                end
            end
        end)
    end
    if type(options.discord) == "string" then
        window:setDiscordInvite(options.discord)
    elseif type(options.discord) == "table" then
        window:setDiscordInvite(options.discord.invite, options.discord.promptOnFirstLaunch)
    end
    return window, window.flags
end
tabClass.new = function(window, tabName: string)
    assert(type(window) == "table", `invalid argument #1 to 'tabClass.new' (table expected, got {type(window)})`)
    window.tabSettings.index += 1

    local tab = setmetatable({
        id = window.tabSettings.index,
        active = window.tabSettings.index == 1 and true or false,
        window = window,
        name = tabName or `tab{window.tabSettings.index}`,

        offsets = { 10, 10 },

        drawings = {},
        allDrawings = {},
        toggleDrawings = {},
    }, tabClass)

    do
        local d, z = tab.drawings, window.baseZindex
        d.fill = square(window, nil, vector2(0, 0), vector2(0, 0), palette.base, z + 3)
        d.outline = square(window, nil, vector2(0, 0), vector2(0, 0), palette.border, z + 4, false)
        d.accent = square(window, nil, vector2(0, 0), vector2(0, 2), window.accent, z + 4)
        d.text = label(window, nil, vector2(0, 0), tab.name, palette.muted, z + 4, true)
    end

    tab.onClicked = function()
        if tab.active then
            return
        end

        local allTabs = tab.window.tabSettings.tabs
        for i = 1, #allTabs do
            local tab2 = allTabs[i]
            if tab2 ~= tab then
                tab2:toggle(false)
            end
        end

        tab:toggle(true)
    end
    tab.window:onClick(tab.drawings.outline, tab.onClicked)

    table_insert(window.tabSettings.tabs, tab)

    tab:toggle(tab.active)
    window:reloadTabs()

    return tab
end
toggleClass.new = function(tab, options: table, offset: number)
    assert(type(tab) == "table", `invalid argument #1 to 'toggleClass.new' (table expected, got {type(tab)})`)
    assert(type(options) == "table", `invalid argument #2 to 'toggleClass.new' (table expected, got {type(options)})`)
