    }, toggleClass)

    toggle.flag = newFlag(toggle, "toggle", toggle.enabled, options)

    do
        local d, w, list, z = toggle.drawings, toggle.window, tab.allDrawings, toggle.window.baseZindex
        local pos = w.drawings[`sectionOutline{offset}`].Position + vector2(13, tab.offsets[offset] + 2)
        d.background = square(w, list, pos, vector2(11, 11), palette.raised, z + 4)
        d.outline = square(w, list, pos, vector2(11, 11), palette.border, z + 5, false)
        d.edge = square(w, list, pos + vector2(1, 1), vector2(9, 9), palette.edge, z + 5, false)
        d.accent = square(w, list, pos + vector2(2, 2), vector2(7, 7), w.accent, z + 6)
        d.accent.Transparency = toggle.enabled and 1 or 0
        d.text = label(
            w,
            list,
            pos + vector2(18, -2),
            toggle.text,
            toggle.risky and color_rgb(220, 177, 101) or palette.text,
            z + 5
        )
        d.clickDetector = square(w, list, pos - vector2(0, 2), vector2(20 + d.text.TextBounds.X, 16), palette.panel, 0)
        d.clickDetector.Transparency = 0
        for _, drawing in d do
            drawing.Visible = tab.active
        end
    end

    toggle.setValue = function(value)
        if toggle.window.destroyed then
            return
        end
        toggle.enabled = value
        toggle.flag.value = value
        toggle.drawings.accent.Transparency = value and 1 or 0
        toggle.flag.Changed(value)
    end
    toggle.onClicked = function()
        toggle.setValue(not toggle.enabled)
    end

    toggle.window:onClick(toggle.drawings.clickDetector, function()
        toggle:onClicked()
    end)
    tab.offsets[offset] += 20

    layoutToggle(toggle)
    return toggle
end
sliderClass.new = function(tab, options: table, offset: number)
    assert(type(tab) == "table", `invalid argument #1 to 'sliderClass.new' (table expected, got {type(tab)})`)
    assert(type(options) == "table", `invalid argument #2 to 'sliderClass.new' (table expected, got {type(options)})`)
    assert(type(offset) == "number", `invalid argument #3 to 'sliderClass.new' (number expected, got {type(offset)})`)

    offset = math_round(math_clamp(offset, 1, 2))
    assert(
        finite(options.min) and finite(options.max) and options.max > options.min,
        "slider.max must exceed slider.min"
    )
    assert(
        options.increment == nil or (finite(options.increment) and options.increment > 0),
        "slider.increment must be positive"
    )
    local slider = setmetatable({
        tab = tab,
        window = tab.window,

        text = options.text,
        value = options.default or options.min,
        max = options.max,
        min = options.min,
        increment = options.increment or 1,
        suffix = options.suffix or "",

        drawings = {},
    }, sliderClass)

    slider.range = slider.max - slider.min
    slider.value = finite(slider.value) and math_clamp(slider.value, slider.min, slider.max) or slider.min

    local stringIncrement = tostring(slider.increment)
    local dotIndex = string_find(stringIncrement, ".", 1, true)
    if dotIndex then
        slider.maxIndex = #stringIncrement - dotIndex
    end

    slider.flag = newFlag(slider, "slider", slider.value, options)

    do
        local d, w, list, z = slider.drawings, slider.window, tab.allDrawings, slider.window.baseZindex
        local pos = w.drawings[`sectionOutline{offset}`].Position + vector2(13, tab.offsets[offset])
        local width = w.drawings.sectionOutline1.Size.X - 26
        d.text = label(w, list, pos, slider.text, palette.text, z + 5)
        d.outline = square(w, list, pos + vector2(0, 17), vector2(width, 7), palette.border, z + 5, false)
        d.background =
            square(w, list, d.outline.Position + vector2(1, 1), d.outline.Size - vector2(2, 2), palette.raised, z + 4)
        d.accent = square(
            w,
            list,
            d.outline.Position + vector2(1, 1),
            vector2((width - 2) * (slider.value - slider.min) / slider.range, 5),
            w.accent,
            z + 5
        )
        d.value = label(w, list, pos, slider.value .. slider.suffix, palette.muted, z + 5)
        d.value.Position = pos + vector2(width - d.value.TextBounds.X, 0)
        d.clickDetector = square(w, list, pos + vector2(0, 13), vector2(width, 15), palette.panel, 0)
        d.clickDetector.Transparency = 0
        for _, drawing in d do
            drawing.Visible = tab.active
        end
    end

    slider.setValue = function(value)
        if slider.window.destroyed or not finite(value) then
            return
        end
        slider.value = math_clamp(value, slider.min, slider.max)
        slider.flag.value = slider.value
        updateSlider(slider)
        slider.flag.Changed(slider.value)
    end
    slider.onClicked = function()
        startDrag(slider.window, function()
            local track = slider.drawings.outline
            local percentage =
                math_clamp((userInputService:GetMouseLocation().X - track.Position.X) / track.Size.X, 0, 1)
            local value = math_clamp(
                math_round(slider.range * percentage / slider.increment) * slider.increment + slider.min,
                slider.min,
                slider.max
            )
            if percentage == 1 then
                value = slider.max
            end
            if value ~= slider.value then
                slider.setValue(value)
            end
        end)
    end
    updateSlider(slider)

    slider.window:onClick(slider.drawings.clickDetector, slider.onClicked)

    tab.offsets[offset] += 35

    return slider
end
