keypickerClass.new = function(toggle, options: table)
    assert(type(toggle) == "table", `invalid argument #1 to 'keypickerClass.new' (table expected, got {type(toggle)})`)
    assert(
        type(options) == "table",
        `invalid argument #2 to 'keypickerClass.new' (table expected, got {type(options)})`
    )

    toggle.hasKeypicker = true
    local keypicker = setmetatable({
        tab = toggle.tab,
        toggle = toggle,
        window = toggle.window,
        active = false,
        value = KEY_CONVERSION[options.default] or options.default or "None",
        blacklisted = options.blacklisted or {},
        mode = options.mode or "toggle",

        drawings = {},
    }, keypickerClass)

    keypicker.flag = newFlag(keypicker, "keypicker", false, options)

    do
        local drawings = keypicker.drawings

        drawings.text = createDrawing("Text", {
            Visible = keypicker.tab.active,

            Outline = true,
            Transparency = 1,
            Size = GLOBAL_SIZE,
            Font = GLOBAL_FONT,
            Text = "[ loading ]",
            Color = palette.text,
            OutlineColor = color_rgb(0, 0, 0),

            ZIndex = keypicker.window.baseZindex + 6,
        }, keypicker.window.allDrawings, keypicker.tab.allDrawings)

        drawings.clickDetector = createDrawing("Square", {
            Visible = keypicker.tab.active,
            Filled = false,
            Transparency = 1,
            Thickness = 1,
            Color = palette.base,
            Position = nil,
            Size = nil,
            ZIndex = 0,
        }, keypicker.window.allDrawings, keypicker.tab.allDrawings)
    end

    local function keyName(key)
        local name = key.KeyCode.Name
        if name == "Unknown" then
            name = key.UserInputType.Name
            if name ~= "MouseButton2" then
                return
            end
        end
        return name
    end
    keypicker.setValue = function(value, key)
        if keypicker.window.destroyed then
            return
        end
        if keypicker.window.capture == keypicker then
            keypicker.window.capture = nil
        end
        keypicker.active = false
        keypicker.value = KEY_CONVERSION[key] or key or "None"
        keypicker.flag.value = value
        keypicker.flag.key = keypicker.value
        keypicker:update()
        keypicker.flag.Changed(value)
        if not keypicker.window.destroyed then
            keypicker.flag.KeyChanged(keypicker.flag.key)
        end
    end
    local onKeyPress = function(key, gameProcessed)
        if keypicker.window.destroyed or userInputService:GetFocusedTextBox() then
            return
        end
        local name = keyName(key)
        if not name then
            return
        end
        if keypicker.active then
            if not keypicker.window.active or not keypicker.tab.active then
                cancelCapture(keypicker.window)
                return
            end
            if name == "Escape" then
                cancelCapture(keypicker.window)
                return
            end
            local converted = KEY_CONVERSION[name] or name
            for _, blocked in keypicker.blacklisted do
                if blocked == name or blocked == converted then
                    return
                end
            end
            keypicker.active = false
            keypicker.window.capture = nil
            keypicker.value = converted
            keypicker.flag.key = converted
            keypicker:update()
            keypicker.flag.KeyChanged(converted)
            return
        end
        if gameProcessed or keypicker.window.capture or keypicker.value == "None" then
            return
        end
        if keypicker.value == (KEY_CONVERSION[name] or name) then
            local value = keypicker.mode ~= "toggle" or not keypicker.flag.value
            keypicker.flag.value = value
            keypicker.flag.Changed(value)
        end
    end
    local onKeyEnd = function(key)
        if keypicker.window.destroyed or keypicker.active or keypicker.mode == "toggle" then
            return
        end
        local name = keyName(key)
        if name and keypicker.value == (KEY_CONVERSION[name] or name) then
            keypicker.flag.value = false
            keypicker.flag.Changed(false)
        end
    end
    local onClicked = function()
        if keypicker.active then
            keypicker.setValue(false, "None")
            return
        end
        cancelCapture(keypicker.window)
        keypicker.active = true
        keypicker.window.capture = keypicker
        keypicker.flag.value = false
        keypicker:update()
        keypicker.flag.Changed(false)
    end
    keypicker.onKeyPress = onKeyPress
    keypicker.window.keypickers = keypicker.window.keypickers or {}
    table_insert(keypicker.window.keypickers, keypicker)
    toggle.keypicker = keypicker
    keypicker.window:onClick(keypicker.drawings.clickDetector, onClicked)
    keypicker.window:addKeyDetector(onKeyPress)
    keypicker.window:addKeyEnd(onKeyEnd)
    keypicker.drawings.clickDetector.Transparency = 0
    keypicker:update()

    return keypicker
end
colourpickerClass.new = function(toggle, options: table)
    assert(type(toggle) == "table", `invalid argument #1 to 'keypickerClass.new' (table expected, got {type(toggle)})`)
    assert(
