    colourpicker.setValue = function(value)
        if colourpicker.window.destroyed then
            return
        end
        colourpicker.value = value
        colourpicker.flag.value = value
        colourpicker:update()
        colourpicker.flag.Changed(value)
    end
    local toggled_onClick = function()
        local window, d = colourpicker.window, colourpicker.drawings
        local active = not d.background_fill.Visible
        closePopup(window)
        if not active then
            return
        end
        local view, base, size = viewport(), window.drawings.base, d.background_fill.Size
        local minX, minY = math.max(2, base.Position.X + 2), math.max(2, base.Position.Y + 2)
        local maxX = math.max(minX, math.min(view.X - 2, base.Position.X + base.Size.X - 2) - size.X)
        local maxY = math.max(minY, math.min(view.Y - 2, base.Position.Y + base.Size.Y - 2) - size.Y)
        minX = math.min(minX, math.max(2, view.X - size.X - 2))
        minY = math.min(minY, math.max(2, view.Y - size.Y - 2))
        maxX = math.min(maxX, math.max(minX, view.X - size.X - 2))
        maxY = math.min(maxY, math.max(minY, view.Y - size.Y - 2))
        local desired = d.colour_outline.Position + vector2(d.colour_outline.Size.X - size.X, 17)
        if desired.Y > maxY then
            desired = vector2(desired.X, d.colour_outline.Position.Y - size.Y - 6)
        end
        local position =
            vector2(math_round(math_clamp(desired.X, minX, maxX)), math_round(math_clamp(desired.Y, minY, maxY)))
        local delta = position - d.background_fill.Position
        for _, drawing in colourpicker.onToggle do
            drawing.Position += delta
            drawing.Visible = true
        end
        local huefill, overlay = window.cachedImages.cp_huefill.drawing, window.cachedImages.cp_overlay.drawing
        huefill.Position = d.hue_outline.Position
        overlay.Position = d.colourpicker_fill.Position
        huefill.Visible = true
        overlay.Visible = true
        window.popup = colourpicker
    end
    local hue_onClick = function()
        startDrag(colourpicker.window, function()
            local d = colourpicker.drawings
            local percentage = math_clamp(
                (userInputService:GetMouseLocation().Y - d.hue_outline.Position.Y) / d.hue_outline.Size.Y,
                0,
                1
            )
            if percentage == colourpicker.h then
                return
            end
            colourpicker.h = percentage
            d.huepicker.Position = d.hue_outline.Position
                + vector2(-2, math_round((d.hue_outline.Size.Y - 6) * percentage))
            d.huepicker_outline.Position = d.huepicker.Position
            colourpicker:updateHue()
        end)
    end
    local colourpick_onClick = function()
        startDrag(colourpicker.window, function()
            local d = colourpicker.drawings
            local percentage = (userInputService:GetMouseLocation() - d.colourpicker_outline.Position)
                / d.colourpicker_outline.Size
            local saturation, value = math_clamp(percentage.X, 0, 1), 1 - math_clamp(percentage.Y, 0, 1)
            if saturation == colourpicker.s and value == colourpicker.v then
                return
            end
            colourpicker.s, colourpicker.v = saturation, value
            local bounds = d.colourpicker_outline.Size - vector2(6, 6)
            local position = d.colourpicker_outline.Position
                + vector2(math_round(bounds.X * saturation), math_round(bounds.Y * (1 - value)))
            d.colourpick.Position = position
            d.colourpick_outline.Position = position
            colourpicker:update_SaturationValue()
        end)
    end

    colourpicker.window:onClick(colourpicker.drawings.colour_outline, toggled_onClick)
    colourpicker.window:onClick(colourpicker.drawings.hue_outline, hue_onClick, nil, true)
    colourpicker.window:onClick(colourpicker.drawings.colourpicker_outline, colourpick_onClick, nil, true)

    colourpicker:update()

    layoutToggle(toggle)
    return colourpicker
end

do
    function notifyClass:moveTo(position, time)
        if self.destroyed then
            return
        end
        time = finite(time) and math.max(0, time) or 0
        if self.move_connection then
            self.move_connection:Disconnect()
            self.move_connection = nil
        end

        local allDrawings = self.drawings
        local basePos = allDrawings.background.Position
        local offset = position - basePos

        local basePositions = {}
        for i, drawing in allDrawings do
            basePositions[i] = drawing.Position
        end

        local totalTime = 0
        self.move_connection = connect(self, runService.RenderStepped, function(deltaTime)
            totalTime += deltaTime
            if totalTime >= time then
                for i, position in basePositions do
                    allDrawings[i].Position = position + offset
                end
                self.move_connection:Disconnect()
                self.move_connection = nil
                return
            end

            local percentage = totalTime / time
            for i, position in basePositions do
                allDrawings[i].Position = position + offset * percentage
            end
        end)
    end

    function notifyClass:remove()
        if self.removing or self.destroyed then
            return
        end
        self.removing = true
        if self.connection then
            self.connection:Disconnect()
        end
        local notifications = self.window.notifications
        local allDrawings = self.drawings

        local offset = self.offset + 10
        local index = table_find(notifications, self)

        table_remove(notifications, index)
        self:moveTo(vector2(10, -offset), 0.05)

        local totalTime = 0
        self.connection = connect(self, runService.RenderStepped, function(deltaTime)
            totalTime += deltaTime

            if totalTime >= 0.05 then
                self:destroy()
                self.connection:Disconnect()
                return
            end
        end)
        for i = 1, #notifications do
            if i < index then
                continue
            end
            local notification = notifications[i]
            notification.goalPos -= vector2(0, offset)
            notification:moveTo(notification.goalPos, 0.05)
        end
    end
end

do
    function boardClass:toggle(enabled)
        if (self.window or self).destroyed then
            return
        end
        if enabled == nil then
            enabled = not self.active
        end
        self.active = enabled
        stopDrag(self)

        for i = 1, #self.allDrawings do
            self.allDrawings[i].Visible = enabled
        end

        for _, drawing in self.cachedDrawings do
            drawing.Visible = false
        end
        if enabled then
            for _, textInfo in self.storedText do
                textInfo.drawing.Visible = textInfo.shown
            end
        end
    end

    function boardClass:isWithin(drawing, mousePosition)
        local size = drawing.Size
        local offset = mousePosition - drawing.Position

        return (offset.X >= 0 and offset.Y >= 0 and offset.X < size.X and offset.Y < size.Y)
    end
    function boardClass:onClick(drawing, onClick)
        local onClicked = function(mousePosition)
            if drawing.Visible and self:isWithin(drawing, mousePosition) then
                return onClick(mousePosition)
            end
        end
        table_insert(self.clickDetectors, onClicked)
    end

    function boardClass:getScale()
        return self.drawings.base.Position / viewport()
    end
    function boardClass:setScale(scale: Vector2)
        if (self.window or self).destroyed then
            return
        end

        local position = scale * viewport()
        local offset = position - self.drawings.base.Position

        stopDrag(self)

        for i = 1, #self.allDrawings do
            self.allDrawings[i].Position += offset
        end
    end

    function boardClass:addText(side, text, colour, shown)
        if (self.window or self).destroyed then
            return
        end

        local textInfo = {
            side = side,
            text = text,
            shown = shown == nil and true or shown,
            colour = colour,
            drawing = self.cachedDrawings[1],
        }

        if not textInfo.drawing then
            textInfo.drawing = createDrawing("Text", {
                Visible = (self.active and textInfo.shown) or false,
                Center = false,
                Outline = true,
                Transparency = 1,
                Size = GLOBAL_SIZE,
                Font = GLOBAL_FONT,
                Text = textInfo.text,
                Color = textInfo.colour,
                OutlineColor = color_rgb(0, 0, 0),

                ZIndex = 9,
            }, self.allDrawings)
        else
            table_remove(self.cachedDrawings, 1)

            textInfo.drawing.Visible = (self.active and textInfo.shown) or false
            textInfo.drawing.Color = textInfo.colour
            textInfo.drawing.Text = textInfo.text
        end

        local index = 0
        for i = 1, #self.storedText do
            if self.storedText[i].side == textInfo.side and self.storedText[i].shown then
                index += 1
            end
        end

        textInfo.drawing.Position = self.drawings.base.Position
            + vector2(
                side == "left" and 8 or self.drawings.base.Size.X - textInfo.drawing.TextBounds.X - 8,
                index * 20 + 27
            )

        table_insert(self.storedText, textInfo)
        self:update()
        return textInfo
    end
    function boardClass:removeText(side, text)
        if (self.window or self).destroyed then
            return
        end
        for i, info in self.storedText do
            if info.side == side and info.text == text then
                stopDrag(self)
                info.drawing.Visible = false
                table_insert(self.cachedDrawings, info.drawing)
                table_remove(self.storedText, i)
                self:update()
                return
            end
        end
    end

    function boardClass:update()
        if (self.window or self).destroyed then
            return
        end

        local leftIndex = 0
        local rightIndex = 0
        local rowWidths, rightRow = {}, 0
        for _, info in self.storedText do
            if info.shown and info.side == "right" then
                fitText(info.drawing, info.text, self.drawings.base.Size.X - 16)
                rowWidths[rightRow] = info.drawing.TextBounds.X
                rightRow += 1
            end
        end

        for _, textInfo in self.storedText do
            local drawing = textInfo.drawing
            local side = textInfo.side

            drawing.Visible = self.active and textInfo.shown

            if not (textInfo.text == drawing.Text and textInfo.colour == drawing.Color) then
                drawing.Text = textInfo.text
                drawing.Color = textInfo.colour
            end
            if textInfo.shown then
                local reserved = side == "left" and rowWidths[leftIndex] or nil
                fitText(drawing, textInfo.text, self.drawings.base.Size.X - 16 - (reserved and (reserved + 10) or 0))

                textInfo.drawing.Position = self.drawings.base.Position
                    + vector2(
                        side == "left" and 8 or self.drawings.base.Size.X - textInfo.drawing.TextBounds.X - 8,
                        (side == "left" and leftIndex or rightIndex) * 20 + 27
                    )

                if textInfo.side == "left" then
                    leftIndex += 1
                else
                    rightIndex += 1
                end
            end
        end

        local ySize = 27 + math.max(leftIndex, rightIndex) * 20
        local xSize = self.drawings.base.Size.X

        self.drawings.base.Size = vector2(xSize, ySize)
        self.drawings.baseOutline.Size = vector2(xSize + 2, ySize + 2)
    end

    function boardClass:findText(side, text)
        for _, textInfo in self.storedText do
            if textInfo.text == text and textInfo.side == side then
                return textInfo
            end
        end
    end
end

