local function inviteCode(value)
    if type(value) ~= "string" then
        return nil
    end
    local code = value:match("^%s*(.-)%s*$")
    code = code:gsub("^https?://", ""):gsub("^www%.", "")
    code = code:match("^discord%.gg/([^/?#]+)")
        or code:match("^discord%.com/invite/([^/?#]+)")
        or code:match("^discordapp%.com/invite/([^/?#]+)")
        or code
    if #code == 0 or #code > 100 or not code:match("^[%w_-]+$") then
        return nil
    end
    return code
end

local function discordEnvironment()
    return type(getgenv) == "function" and getgenv() or getfenv()
end

local function discordRegistry(environment)
    local registry = environment.__UIDiscordInvites
    if type(registry) ~= "table" or type(registry.attempted) ~= "table" or type(registry.inFlight) ~= "table" then
        registry = { attempted = {}, inFlight = {} }
        environment.__UIDiscordInvites = registry
    end
    return registry
end

local function discordRequest(environment)
    for _, name in ipairs({ "request", "http_request", "httprequest" }) do
        if type(environment[name]) == "function" then
            return environment[name]
        end
    end
    for _, name in ipairs({ "http", "syn", "fluxus" }) do
        local provider = environment[name]
        if type(provider) == "table" and type(provider.request) == "function" then
            return provider.request
        end
    end
    return nil
end

function windowClass:openDiscordInvite(automatic)
    local code = self.discordInvite
    if self.destroyed or not code then
        return false
    end
    local environment = discordEnvironment()
    local registry = discordRegistry(environment)
    if registry.inFlight[code] or (automatic and registry.attempted[code]) then
        return false
    end
    local token = {}
    registry.inFlight[code] = token
    self.discordStatus = "pending"
    task_spawn(function()
        local completed, timedOut = false, false
        local function unavailable(message)
            if not self.destroyed and self.discordInvite == code then
                self.discordStatus = "unavailable"
                self:notify(message or "Discord is unavailable. Use Copy invite.", 5)
            end
        end
        local ok, result = pcall(function()
            local path = "ui-discord-prompt-" .. code .. ".txt"
            if automatic and type(environment.readfile) == "function" then
                local read, contents = pcall(environment.readfile, path)
                if read and contents == "attempted" then
                    registry.attempted[code] = true
                    return "remembered"
                end
            end
            if self.destroyed or self.discordInvite ~= code then
                return "cancelled"
            end
            registry.attempted[code] = true
            if type(environment.writefile) == "function" then
                pcall(environment.writefile, path, "attempted")
            end
            local request = discordRequest(environment)
            if not request then
                return "unavailable"
            end
            local httpService = game:GetService("HttpService")
            task_delay(8, function()
                if not completed then
                    timedOut = true
                    unavailable("Discord did not respond. Use Copy invite.")
                end
            end)
            local response = request({
                Url = "http://127.0.0.1:6463/rpc?v=1",
                Method = "POST",
                Headers = {
                    ["Content-Type"] = "application/json",
                    Origin = "https://discord.com",
                },
                Body = httpService:JSONEncode({
                    cmd = "INVITE_BROWSER",
                    args = { code = code },
                    nonce = httpService:GenerateGUID(false),
                }),
                Timeout = 5,
            })
            if type(response) ~= "table" or response.Success == false then
                return "unavailable"
            end
            local status = tonumber(response.StatusCode or response.Status)
            if not status or status < 200 or status >= 300 then
                return "unavailable"
            end
            if type(response.Body) == "string" and response.Body ~= "" then
                local decoded, body = pcall(httpService.JSONDecode, httpService, response.Body)
                if decoded and type(body) == "table" and (body.evt == "ERROR" or body.cmd == "ERROR") then
                    return "unavailable"
                end
            end
            return "requested"
        end)
        completed = true
        if registry.inFlight[code] == token then
            registry.inFlight[code] = nil
        end
        if self.destroyed or self.discordInvite ~= code then
            return
        end
        if not ok or result == "unavailable" then
            if not timedOut then
                unavailable()
            end
        elseif result ~= "cancelled" then
            self.discordStatus = result
        end
    end)
    return true
end

function windowClass:copyDiscordInvite()
    if self.destroyed or not self.discordInvite then
        return false
    end
    local environment = discordEnvironment()
    local clipboard = type(environment.setclipboard) == "function" and environment.setclipboard
        or environment.toclipboard
    local url = "https://discord.gg/" .. self.discordInvite
    if type(clipboard) ~= "function" or not pcall(clipboard, url) then
        self:notify("Clipboard unavailable: discord.gg/" .. self.discordInvite, 6)
        return false
    end
    self:notify("Invite copied.", 3)
    return true
end

function windowClass:setDiscordInvite(invite, promptOnFirstLaunch)
    if self.destroyed then
        return false
    end
    local code = inviteCode(invite)
    if invite ~= nil and not code then
        return false
    end
    self.discordInvite = code
    self.discordStatus = code and "ready" or nil
    local d, z = self.drawings, self.baseZindex
    if code and not d.discordButton then
        local position = d.base.Position + vector2(self.size.X - 150, 7)
        d.discordButton = square(self, nil, position, vector2(58, 17), palette.panel, z + 4)
        d.discordOutline = square(self, nil, position, vector2(58, 17), palette.border, z + 5, false)
        d.discordLabel = label(self, nil, position + vector2(29, 1), "Discord", palette.text, z + 6, true)
        local copyPosition = position + vector2(64, 0)
        d.discordCopyButton = square(self, nil, copyPosition, vector2(78, 17), palette.panel, z + 4)
        d.discordCopyOutline = square(self, nil, copyPosition, vector2(78, 17), palette.border, z + 5, false)
        d.discordCopyLabel = label(self, nil, copyPosition + vector2(39, 1), "Copy invite", palette.muted, z + 6, true)
        self:onClick(d.discordButton, function()
            self:openDiscordInvite()
        end)
        self:onClick(d.discordCopyButton, function()
            self:copyDiscordInvite()
        end)
    end
    if d.discordButton then
        for _, name in ipairs({
            "discordButton",
            "discordOutline",
            "discordLabel",
            "discordCopyButton",
            "discordCopyOutline",
            "discordCopyLabel",
        }) do
            d[name].Visible = code ~= nil
        end
    end
    d.onDrag.Size = vector2(code and self.size.X - 156 or self.size.X, 27)
    fitText(d.title, self.title, self.size.X - (code and 170 or 20))
    if code and promptOnFirstLaunch ~= false then
        task_delay(0, function()
            if not self.destroyed and self.discordInvite == code then
                self:openDiscordInvite(true)
            end
        end)
    end
    return true
end

do
    function windowClass:addTab(tabName: string)
        if self.destroyed then
            return
        end
        return tabClass.new(self, tabName)
    end
    function windowClass:reloadTabs()
        if self.destroyed then
            return
        end
        local tabs = self.tabSettings.tabs
        for i = 1, #tabs do
            tabs[i]:reload()
        end
    end
    function windowClass:isWithin(drawing, mousePosition)
        local size = drawing.Size
        local offset = mousePosition - drawing.Position

        return (offset.X >= 0 and offset.Y >= 0 and offset.X < size.X and offset.Y < size.Y)
    end
    function windowClass:onClick(drawing, onClick, onMiss, ignoreOverlap)
        onMiss = onMiss or function(...) end
        local onClicked = function(mousePosition)
            if not (drawing.Visible and self:isWithin(drawing, mousePosition)) then
                return onMiss(mousePosition)
            elseif ignoreOverlap then
                return onClick(mousePosition)
            end

            for i = 1, #self.overlapDrawings do
                local overlapDrawing = self.overlapDrawings[i]
                if overlapDrawing.Visible and self:isWithin(overlapDrawing, mousePosition) then
                    return onMiss(mousePosition)
                end
            end

            return onClick(mousePosition)
        end

        table_insert(self.clickDetectors, onClicked)
    end
    function windowClass:toggle()
        if self.destroyed then
            return
        end
        stopDrag(self)
        closePopup(self)
        cancelCapture(self)
        local enabled = not self.active
        self.active = enabled
        local offset = enabled and vector2(99999, 99999) or vector2(-99999, -99999)
        for _, drawing in self.allDrawings do
            drawing.Position += offset
        end
        for _, callback in table.clone(self.connectedToggles) do
            if self.destroyed or self.active ~= enabled then
                break
            end
            task_spawn(callback, enabled)
        end
    end

    function windowClass:onToggle(_function)
        table_insert(self.connectedToggles, _function)
    end
    function windowClass:addKeyDetector(_function)
        table_insert(self.keyDetectors, _function)
    end
    function windowClass:addKeyEnd(_function)
        table_insert(self.keyEnd, _function)
    end
    function windowClass:notify(text, time)
        if self.destroyed then
            return
        end
        return notifyClass.new(self, text, time)
    end
end

do
    function tabClass:reload()
        if self.window.destroyed then
            return
        end
        local frame, total = self.window.drawings.innerOutline, self.window.tabSettings.index
        local left = math.floor(frame.Size.X * (self.id - 1) / total)
        local right = math.floor(frame.Size.X * self.id / total)
        local d = self.drawings
        d.outline.Position = frame.Position + vector2(left, 0)
        d.outline.Size = vector2(right - left, 27)
        d.fill.Position = d.outline.Position + vector2(1, 1)
        d.fill.Size = vector2(math.max(0, d.outline.Size.X - 2), 25)
        d.accent.Position = d.outline.Position + vector2(1, 25)
        d.accent.Size = vector2(math.max(0, d.outline.Size.X - 2), 1)
        d.text.Position = d.outline.Position + vector2(math.floor(d.outline.Size.X / 2), 6)
        fitText(d.text, self.name, math.max(0, d.outline.Size.X - 12))
    end

    function tabClass:toggle(enabled: boolean?)
        if enabled == nil then
            enabled = not self.active
        end

        if self.window.destroyed then
            return
        end
        stopDrag(self.window)
        closePopup(self.window)
        cancelCapture(self.window)
        if enabled then
            for _, tab in self.window.tabSettings.tabs do
                if tab ~= self and tab.active then
                    tab:toggle(false)
                end
            end
        end
        self.active = enabled
        self.window.mouseHeld = false
        self.drawings.fill.Color = enabled and palette.raised or palette.base
        self.drawings.accent.Transparency = enabled and 1 or 0

        local allDrawings = self.allDrawings
        if enabled then
            self.drawings.text.Color = self.window.accent
            for i = 1, #allDrawings do
                allDrawings[i].Visible = true
            end
        else
            local toggleDrawings = self.toggleDrawings
            self.drawings.text.Color = palette.muted
            for i = 1, #allDrawings do
                allDrawings[i].Visible = false
            end
            for i = 1, #toggleDrawings do
                toggleDrawings[i].Visible = false
            end
        end
    end

    function tabClass:addToggle(options: table, offset: number)
        if self.window.destroyed then
            return
        end
        return toggleClass.new(self, options, offset)
    end

    function tabClass:addSlider(options: table, offset: number)
        if self.window.destroyed then
            return
        end
        return sliderClass.new(self, options, offset)
    end

    function tabClass:addDropdown(options: table, offset: number)
        if self.window.destroyed then
            return
        end
        return dropdownClass.new(self, options, offset)
    end

    function tabClass:addButton(text: string, onClick, offset: number)
        if self.window.destroyed then
            return
        end
        return buttonClass.new(self, text, onClick, offset)
    end
end

