do
    function colourpickerClass:update()
        if (self.window or self).destroyed then
            return
        end
        local drawings = self.drawings
        self.h, self.s, self.v = self.value:ToHSV()

        drawings.colourpicker_fill.Color = color_hsv(self.h, 1, 1)
        drawings.colour_fill.Color = self.value

        local hueOutline = drawings.hue_outline
        local colourpickerOutline = drawings.colourpicker_outline

        local maxColourBounds = colourpickerOutline.Size - vector2(6, 6)
        local maxHueBound = hueOutline.Size.Y - 6

        drawings.huepicker.Position = hueOutline.Position + vector2(-2, maxHueBound * self.h)
        drawings.huepicker_outline.Position = drawings.huepicker.Position

        drawings.colourpick.Position = colourpickerOutline.Position
            + vector2(maxColourBounds.X * self.s, maxColourBounds.Y * math_abs(self.v - 1))
        drawings.colourpick_outline.Position = drawings.colourpick.Position
    end

    function colourpickerClass:updateHue()
        if (self.window or self).destroyed then
            return
        end
        local drawings = self.drawings
        local value = color_hsv(self.h, self.s, self.v)

        drawings.colourpicker_fill.Color = color_hsv(self.h, 1, 1)
        drawings.colour_fill.Color = value

        self.value = value
        self.flag.value = value
        self.flag.Changed(value)
    end

    function colourpickerClass:update_SaturationValue()
        if (self.window or self).destroyed then
            return
        end
        local value = color_hsv(self.h, self.s, self.v)
        self.drawings.colour_fill.Color = value

        self.value = value
        self.flag.value = value
        self.flag.Changed(value)
    end
